async function loadOriginalCompositions(){originalLoading=true;try{const r=await fetch(API_URL+'/api/v1/catalog/songs?limit=100');if(!r.ok)throw Error('catalog');const data=await r.json();publishedSongs=(data.data||[]).filter(s=>s.status==='published'&&(s.accessTier||'free')==='free');originalCompositions=publishedSongs.filter(s=>s.source==='original'&&/^(deepak|deepak sharma)$/i.test(String(s.artist||'').trim())&&s.featuredOwnComposition===true);}catch{originalCompositions=[];}originalLoading=false;render();if(publishedSongs.length)void enrichArtwork(publishedSongs.filter(song=>!song.thumbnailUrl&&!song.artworkUrl));}
