async function submitRating(rating){
 const visitorId=ratingVisitorId();
 if(!visitorId){toast('Rating could not be saved on this device');return;}
 try{
  const response=await fetch('https://lyricsverse-api.onrender.com/api/v1/ratings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rating,visitorId})});
  if(!response.ok)throw Error('rating_save_failed');
  const payload=await response.json();ratingSummary=payload.data;
  localStorage.setItem('lyricverse:user-rating',String(rating));state.rating=rating;render();
 }catch{toast('Rating could not be saved. Please try again.');}
}
