function coverHTML(song,extra=''){const [c1,c2,c3]=song.cover;const art=song.thumbnailUrl||song.artworkUrl||artworkCache.get(song.id);const fallback=generatedSongThumbnail(song);return `<div class="cover-art ${extra}" aria-hidden="true" style="--cover1:${c1};--cover2:${c2};--cover3:${c3}"><img class="song-cover-thumbnail" src="${esc(art||fallback)}" data-fallback="${esc(fallback)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src=this.dataset.fallback"></div>`;}
