function initSongBanner(){const slider=document.querySelector('.song-banner-slider');if(!slider)return;const slides=[...slider.querySelectorAll('.song-banner-slide')],dots=[...document.querySelectorAll('.song-banner-dots button')];if(!slides.length)return;let active=0;const select=index=>{active=(index+slides.length)%slides.length;slider.scrollTo({left:slides[active].offsetLeft-slider.firstElementChild.offsetLeft,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});dots.forEach((dot,i)=>dot.setAttribute('aria-current',String(i===active)));};document.querySelectorAll('[data-banner-step]').forEach(button=>button.addEventListener('click',()=>select(active+Number(button.dataset.bannerStep))));dots.forEach((button,i)=>button.addEventListener('click',()=>select(i)));let frame=0;slider.addEventListener('scroll',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const position=slider.scrollLeft;let nearest=0,distance=Infinity;slides.forEach((slide,i)=>{const d=Math.abs(slide.offsetLeft-slides[0].offsetLeft-position);if(d<distance){distance=d;nearest=i;}});active=nearest;dots.forEach((dot,i)=>dot.setAttribute('aria-current',String(i===active)));});},{passive:true});}
