function heroHTML(){return `<section class="discovery-hero hero-v2 neon-hero" aria-label="Discover song lyrics"><div class="neon-hero-cosmos" aria-hidden="true"><div class="universe-glow universe-glow-magenta"></div><div class="universe-glow universe-glow-blue"></div><div class="neon-wave neon-wave-a"></div><div class="neon-wave neon-wave-b"></div><div class="neon-vinyl"><div class="neon-vinyl-inner"><span>LV</span></div><div class="neon-vinyl-reflection"></div></div><div class="universe-orbit universe-orbit-one"></div><div class="universe-orbit universe-orbit-two"></div><span class="neon-star neon-star-one">✦</span><span class="neon-star neon-star-two">✧</span><span class="neon-music-note">♫</span><div class="universe-track-card"><span class="universe-track-icon">♫</span><span><strong>Discover your sound</strong><small>Every lyric. Every feeling.</small></span><span class="universe-track-bars"><i></i><i></i><i></i><i></i></span></div></div><div class="hero-v2-copy neon-hero-content"><p class="eyebrow">MUSIC LIVES IN WORDS <span class="eyebrow-line"></span> LYRICVERSE</p><h1>Find the words.<br><span class="hero-gradient-text hero-highlight-rotator" data-hero-highlight aria-live="off">${HERO_HIGHLIGHTS[state.heroHighlightIndex||0]}</span></h1><p class="hero-headline-intro">Lyrics for every heartbeat, every journey, every you.</p><div class="hero-search-box neon-hero-search">${searchHTML()}<span class="search-hint">Search a song, artist or lyrics</span></div><div class="hero-actions"><a class="button button-primary hero-cta" href="#/search">Explore lyrics <span aria-hidden="true">↗</span></a><button type="button" class="button button-secondary hero-alt" data-scroll-to="moods">Find your mood <span aria-hidden="true">→</span></button></div><div class="rotator-line" aria-label="What you can do on LyricVerse"><span class="rotator-dot" aria-hidden="true"></span><span class="rotator-heading" aria-live="polite" data-rotator-text>${HERO_MESSAGES[state.headlineIndex]}</span><button type="button" class="rotator-next" data-action="rotate-headline" aria-label="Show next website feature">↗</button><button type="button" class="rotator-next rotator-pause" data-action="pause-rotation" aria-label="Pause headline rotation" aria-pressed="false">Ⅱ</button></div></div></section>`;}
function languageSwitchHTML(){return `<div class="language-switch" role="group" aria-label="Lyrics language"><button type="button" data-language="en" aria-pressed="${state.language==='en'}" class="language-option ${state.language==='en'?'selected':''}">English</button><button type="button" data-language="hi" lang="hi" aria-pressed="${state.language==='hi'}" class="language-option ${state.language==='hi'?'selected':''}">हिन्दी</button><button type="button" data-language="pa" lang="pa" aria-pressed="${state.language==='pa'}" class="language-option ${state.language==='pa'?'selected':''}">ਪੰਜਾਬੀ</button></div>`;}
function availableGenres(){return state.language==='hi'?genresHindi:genresDesktop;}
function availableMobileGenres(){return state.language==='hi'?genresHindi:genresMobile;}
function chipHTML(genre){return `<button type="button" class="chip ${state.filter===genre?'selected':''}" data-genre="${esc(genre)}" aria-pressed="${state.filter===genre}">${esc(genre)}</button>`;}
function ratingHTML(){return `<section class="rating-strip" aria-label="Rate your LyricVerse experience"><div class="rating-title"><span class="rating-sparkle" aria-hidden="true">✦</span><div><strong>Enjoying the experience?</strong><span>Give your first impression — ratings are collected anonymously.</span></div></div><div class="rating-actions"><div class="rating-stars" role="group" aria-label="Rate from one to five stars">${[1,2,3,4,5].map(n=>`<button type="button" class="rating-star ${n<=state.rating?'is-selected':''}" data-rating="${n}" aria-label="Rate ${n} out of 5 stars" aria-pressed="${n===state.rating}">★</button>`).join('')}</div><span class="rating-feedback" aria-live="polite">${state.rating?`Your rating: ${state.rating}/5`:'Be the first to rate'}${ratingSummary.count?` · Average ${ratingSummary.average}/5 (${ratingSummary.count} ratings)`:''}</span></div></section>`;}
function compactLyricCard(song){return `<a class="compact-lyric-card" href="${songHref(song)}" aria-label="View ${esc(song.title)} by ${esc(song.artist)}"><span class="compact-art">${coverHTML(song)}</span><span class="compact-card-copy"><span class="compact-badge">${esc(song.genre)} · DEMO</span><strong lang="${song.language==='hi'?'hi':'en'}">${esc(song.title)}</strong><span class="compact-artist" lang="${song.language==='hi'?'hi':'en'}">${esc(song.artist)}</span><span class="compact-open">Read lyrics <span aria-hidden="true">↗</span></span></span></a>`;}
function featuredVideosHTML(){return `<section class="home-side-section video-section"><div class="side-section-heading"><div><span class="side-kicker">WATCH & DISCOVER</span><h3>Featured videos</h3></div><a href="https://www.youtube.com/@nprmusic" target="_blank" rel="noopener noreferrer" aria-label="Explore NPR Music videos on YouTube">More ↗</a></div><div class="video-list">${FEATURED_VIDEOS.map(v=>`<a class="video-row" href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noopener noreferrer" aria-label="Watch ${esc(v.title)} on YouTube"><span class="video-thumb"><img loading="lazy" decoding="async" src="https://i.ytimg.com/vi/${v.id}/mqdefault.jpg" alt=""><span class="video-play" aria-hidden="true">▶</span></span><span class="video-meta"><strong>${esc(v.title)}</strong><small>${esc(v.by)} · ${esc(v.duration)}</small><span class="video-youtube">YouTube ↗</span></span></a>`).join('')}</div></section>`;}
function usefulLinksHTML(){return `<section class="home-side-section useful-links"><div class="side-section-heading"><div><span class="side-kicker">QUICK ACCESS</span><h3>Useful links</h3></div></div><div class="quick-links"><a href="#/search"><span class="quick-icon">⌕</span><span>Explore all songs</span><span aria-hidden="true">↗</span></a><a href="#/library"><span class="quick-icon">♡</span><span>Your saved songs</span><span aria-hidden="true">↗</span></a><button type="button" data-scroll-to="moods"><span class="quick-icon">♫</span><span>Browse by mood</span><span aria-hidden="true">↗</span></button><button type="button" data-scroll-to="how-it-works"><span class="quick-icon">?</span><span>How LyricVerse works</span><span aria-hidden="true">↗</span></button></div></section>`;}
function lyricsHubHTML(songs){const shown=songs.slice(0,4);return `<section class="homepage-hub" id="lyrics-hub" aria-label="Explore lyrics and music"><div class="lyrics-hub-main"><div class="hub-header"><div><span class="section-kicker">A LITTLE MUSIC, A LOT OF MEANING</span><h2>Explore song lyrics</h2><p>Start with a song. Follow the words wherever they take you.</p></div><a class="small-text-link" href="#/search">View all lyrics ↗</a></div><div class="lyrics-language-bar"><span>Lyrics language</span>${languageSwitchHTML()}</div><div class="compact-lyrics-grid">${shown.length?shown.map(compactLyricCard).join(''):'<p class="no-results">No demo songs in this genre yet. Explore all songs instead.</p>'}</div><a class="explore-lyrics-cta" href="#/search"><span>Explore more lyrics</span><span aria-hidden="true">↗</span></a></div><aside class="homepage-sidebar" aria-label="Watch and explore">${featuredVideosHTML()}${usefulLinksHTML()}</aside></section>`;}
function moodsHTML(){const items=[['Midnight drive','Electronic','Nighttime, neon, new discoveries','mood-night'],['Feel everything','R&B','Every feeling has a soundtrack','mood-heart'],['Golden energy','Pop','A brighter playlist starts here','mood-sun']];return `<section id="moods" class="moods-section"><div class="wide-section-heading"><div><span class="section-kicker">PICK YOUR VIBE</span><h2>Discover by mood</h2><p>Something to match every moment.</p></div><a href="#/search">Browse music ↗</a></div><div class="mood-grid">${items.map(([name,genre,desc,cls])=>`<a href="#/search" data-mood="${genre}" class="mood-card ${cls}"><span class="mood-art" aria-hidden="true">${cls==='mood-night'?'☾':cls==='mood-heart'?'♡':'✳'}</span><span class="mood-copy"><strong>${name}</strong><small>${desc}</small><span>Discover ${genre} <span aria-hidden="true">↗</span></span></span></a>`).join('')}</div></section>`;}
function howHTML(){
 const published=publishedSongs.find(s=>s?.status==='published'&&(s.accessTier||'free')==='free'&&typeof s.lyrics==='string'&&s.lyrics.trim()&&/^[a-f0-9]{24}$/i.test(String(s._id||'')));
 const readingHref=published?'#/original/'+encodeURIComponent(String(published._id)):allSongs[0]?songHref(allSongs[0]):'#/search';
 return `<section id="how-it-works" class="how-section"><div class="wide-section-heading"><div><span class="section-kicker">THE WAY MUSIC SHOULD FEEL</span><h2>More than just words</h2><p>Built for discovery, reading and understanding.</p></div></div><div class="feature-grid"><a href="#/search" class="feature-card lv-feature-link"><span class="feature-number">01 / DISCOVER</span><span class="feature-icon" aria-hidden="true">⌕</span><h3>Find your next favourite</h3><p>Search by song, artist, or genre and move straight to the music.</p><span class="lv-feature-open">Search songs <span aria-hidden="true">↗</span></span></a><a href="${readingHref}" class="feature-card lv-feature-link"><span class="feature-number">02 / READ</span><span class="feature-icon" aria-hidden="true">▤</span><h3>Read without distraction</h3><p>Enjoy a comfortable reading experience with song information and an optional Reading Studio for published lyrics.</p><span class="lv-feature-open">Explore a song <span aria-hidden="true">↗</span></span></a><a href="#/library" class="feature-card lv-feature-link"><span class="feature-number">03 / COLLECT</span><span class="feature-icon" aria-hidden="true">♡</span><h3>Keep your soundtrack close</h3><p>Save your favourite songs to a personal library and revisit them whenever you like.</p><span class="lv-feature-open">Your library <span aria-hidden="true">↗</span></span></a></div></section>`;
}
function socialIcon(type){return ({x:'𝕏',linkedin:'in',facebook:'f',youtube:'▶'})[type];}
function footerHTML(){const url=encodeURIComponent(location.origin+location.pathname+'#/');const title=encodeURIComponent('Discover lyrics and music on LyricVerse');const social=[['x',`https://twitter.com/intent/tweet?text=${title}&url=${url}`,'Share on X'],['linkedin',`https://www.linkedin.com/sharing/share-offsite/?url=${url}`,'Share on LinkedIn'],['facebook',`https://www.facebook.com/sharer/sharer.php?u=${url}`,'Share on Facebook'],['youtube','https://www.youtube.com/@nprmusic','Watch NPR Music on YouTube']];return `<footer class="site-footer"><div class="footer-top"><div class="footer-brand"><a class="wordmark" href="#/"><span aria-hidden="true">▥</span> LyricVerse</a><p>Find the words. Feel the music.<br>Discover, read and explore.</p><div class="footer-social" aria-label="Share LyricVerse and watch music">${social.map(([kind,url,label])=>`<a class="social-icon" href="${url}" target="_blank" rel="noopener noreferrer" aria-label="${label}">${socialIcon(kind)}</a>`).join('')}</div></div><div class="footer-group"><h3>Explore</h3><a href="#/search">Browse lyrics</a><a href="#/search">Popular songs</a><a href="#/library">Saved songs</a></div><div class="footer-group"><h3>About</h3><button type="button" data-scroll-to="how-it-works">How it works</button><button type="button" data-scroll-to="moods">Music by mood</button><a href="#/info/about">Our approach</a></div><div class="footer-group"><h3>Information</h3><a href="#/info/rights">Lyrics & rights</a><a href="#/info/privacy">Privacy</a><a href="#/info/contact">Contact</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} LyricVerse. Discover responsibly.</span><span>Demo song metadata · Lyrics shown only with appropriate permissions</span></div></footer>`;}
function infoHTML(){const slug=currentRoute().slug;const info={about:['Our approach','LyricVerse makes music discovery more readable and accessible. The current site features demo songs and an expanding design built for licensed lyrics.'],rights:['Lyrics & rights','LyricVerse does not display third-party copyrighted lyrics without appropriate authorization. The current song catalog is illustrative. Video links open verified publisher channels.'],privacy:['Privacy','Demo favorites and visitor ratings are saved locally in your browser. No account information is collected through the current prototype.'],contact:['Contact','Contact details for LyricVerse will appear here after a dedicated support address is configured.']};let [heading,desc]=info[slug]||info.about;return `${navHTML()}<main id="app-main" tabindex="-1" class="info-main"><p class="eyebrow">LYRICVERSE / INFORMATION</p><h1>${heading}</h1><p>${desc}</p><a class="button button-primary" href="#/">Back to homepage ↗</a></main>${footerHTML()}${bottomNavHTML()}`;}
function homeHTML(){const catalog=state.language==='hi'?[...hindiSongs,...punjabiSongs]:[...topSongs,...punjabiSongs,...hindiSongs];const matching=state.filter==='All'?catalog:catalog.filter(s=>s.genre===state.filter);return `${navHTML()}<main id="app-main" tabindex="-1" class="homepage-v2 neon-home">${heroHTML()}<div class="neon-genre-strip" id="genres"><span class="section-kicker">EXPLORE YOUR SOUND</span><div class="genres desktop-genres" aria-label="Genres">${availableGenres().map(chipHTML).join('')}</div><div class="genres mobile-genres" aria-label="Genres">${availableMobileGenres().map(chipHTML).join('')}</div></div>${sectionHTML('Trending now',matching.slice(0,8),matching.slice(0,4))}${moodsHTML()}${floatingPearlsHTML(matching)}${mixedSongsHTML()}<div class="home-song-sections">${sectionHTML('New & noteworthy',newSongs.slice(0,8),newSongs.slice(0,4),'fresh-songs')}</div>${ratingHTML()}${howHTML()}<section class="closing-cta neon-closing"><div><span class="section-kicker">A GLOBAL HOME FOR MUSIC LOVERS</span><h2>Find your next favorite song.</h2><p>Discover lyrics, explore artists, and keep the stories alive.</p></div><a class="button button-primary" href="#/search">Discover music ↗</a></section></main>${originalCompositionsHTML()}${footerHTML()}${bottomNavHTML()}`;}
function songMetaBanner(song){return `<section class="song-profile-banner">${coverHTML(song,'reader-art')}<div class="profile-info"><p class="eyebrow">${esc(song.artist.toUpperCase())}</p><h1>${esc(song.title)}</h1><p class="song-metadata"><span class="album-meta">${esc(song.album||'Single')} <span>•</span></span> ${esc(song.year||'2026')} <span>•</span> ${esc(song.genre)}${song.language==='hi'?' <span>•</span> <span lang="hi">हिन्दी</span>':''}</p><div class="profile-actions"><button type="button" class="button button-primary" data-action="preview">▶ Preview</button><button type="button" class="button button-secondary" data-action="save">${state.saved.includes(song.id)?'♥ Saved':'♡ Save'}</button><button type="button" class="button button-secondary" data-action="share">↗ Share</button></div></div></section>`;}
function readerControls(song){return `<div class="reader-tabs" role="tablist" aria-label="Track information">${['Lyrics','About','Meaning','Translations'].map(v=>`<button type="button" role="tab" aria-selected="${state.readerTab===v}" class="chip ${state.readerTab===v?'selected':''}" data-tab="${v}">${v}</button>`).join('')}</div><div class="mobile-reader-controls"><button type="button" class="chip" data-action="save">${state.saved.includes(song.id)?'♥ Saved':'♡ Save'}</button><button type="button" class="chip" data-action="font-size">A− / A+</button><button type="button" class="chip" data-action="translate">Translate</button></div>`;}
function lyricsHTML(song){const isHindiDemo=false;const isReferenceSong=false;let arr=[];let allSections=matchMedia('(max-width: 767px)').matches?arr.slice(0,2).map((block,i)=>({...block,lines:i===1?block.lines.slice(0,3):block.lines})):arr;return `<section class="lyrics-panel" lang="${song.language==='hi'?'hi':'en'}"><h2>LYRICS</h2><p class="lyrics-disclaimer">${isReferenceSong?(matchMedia('(max-width: 767px)').matches?'Original demonstration lyrics • licensed text required':'Original illustrative lyrics only. Licensed real-song lyrics are not connected.') :'Lyrics are not hosted here unless publication rights are confirmed. Open a legitimate lyrics provider to find available lyrics.'}</p>${allSections.map(block=>`<section class="verse"><h3>${esc(block.section)}</h3>${block.lines.map(line=>`<p class="lyric-line">${esc(line)}</p>`).join('')}</section>`).join('')}<p class="licensing-footer"><a class="button button-primary" href="${esc(song.lyricsSearchUrl)}" target="_blank" rel="noopener noreferrer">Find lyrics on Genius ↗</a></p></section>`;}
function infoPanel(song){const title=state.readerTab;return `<section class="lyrics-panel extra-panel"><h2>${title.toUpperCase()}</h2><p>${title==='About'?`${esc(song.title)} by ${esc(song.artist)} — metadata from chart listings; see the source chart for attribution.`:title==='Meaning'?'Song interpretations will only be displayed when sourced and reviewed.':'Translations require suitable lyric and translation rights.'}</p></section>`;}
function relatedHTML(song){const related=allSongs.filter(s=>s.id!==song.id&&(s.language===song.language||s.genre===song.genre));return `<aside class="related-panel"><h2>Related tracks</h2><div class="related-list">${related.slice(0,4).map(song=>`<a class="related-item" href="${songHref(song)}">${coverHTML(song,'related-art')}<div><span class="related-title">${esc(song.title)}</span><span class="related-artist">${esc(song.artist)}</span></div></a>`).join('')}</div></aside>`;}
function youtubePreviewHTML(song){
 const preview=state.youtubePreview;
 const query=encodeURIComponent(song.artist+' '+song.title+' official audio');
 const search='https://www.youtube.com/results?search_query='+query;
 if(!preview&&!state.youtubePreviewLoading)return '';
 if(state.youtubePreviewLoading)return '<section class="youtube-preview-panel" role="status">Finding the song on YouTube…</section>';
 const match=preview?.songId===String(song._id||song.id)?preview:null;
 const id=match?.videoId;
 return `<section class="youtube-preview-panel" aria-label="YouTube song preview"><h2>Listen on YouTube</h2>${id?`<iframe class="youtube-preview-frame" src="https://www.youtube-nocookie.com/embed/${id}?rel=0" title="YouTube preview: ${esc(song.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><p><a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Watch full song on YouTube ↗</a></p>`:`<p>No verified embeddable video found. Search YouTube for this song instead.</p><p><a href="${search}" target="_blank" rel="noopener noreferrer">Find full song on YouTube ↗</a></p>`}</section>`;
}
function readerHTML(){const route=currentRoute();const song=allSongs.find(x=>x.id===route.slug)||readerSong;const uploaded=publishedMatch(song,publishedSongs);if(uploaded)return originalReaderHTMLForSong(uploaded);return `${navHTML()}<main id="app-main" tabindex="-1" class="reader-main neon-reader"><div class="breadcrumb"><a href="#/">Discover</a><span>/</span><span>${esc(song.artist)}</span><span class="desktop-only-crumb">/</span><span class="desktop-only-crumb">${esc(song.title)}</span></div><div class="neon-reader-hero">${songMetaBanner(song)}${readerControls(song)}${youtubePreviewHTML(song)}</div><div class="reader-columns neon-reader-columns">${state.readerTab==='Lyrics'?lyricsHTML(song):infoPanel(song)}${relatedHTML(song)}</div></main>${bottomNavHTML()}`;}
async function loadProviderSearch(){const q=state.query.trim();const request=++providerRequest;providerSongs=[];providerError=false;providerLoading=q.length>=2;if(!providerLoading){render();return;}render();try{const response=await fetch(API_URL+'/api/v1/providers/discovery/search?q='+encodeURIComponent(q));if(!response.ok)throw Error('provider');const data=await response.json();if(request!==providerRequest)return;providerSongs=Array.isArray(data.data)?data.data:[];}catch{if(request!==providerRequest)return;providerError=true;}finally{if(request===providerRequest){providerLoading=false;render();}}}
function providerResultsHTML(){
 const q=state.query.trim();if(!q)return '';
 const matches=localSongMatches(q,{published:publishedSongs,catalog:allSongs});
 const localHTML=matches.length?'<section class="local-lyrics-results" aria-label="LyricVerse songs"><h2>LyricVerse results</h2><p class="library-description">Explore songs and read uploaded lyrics directly on LyricVerse.</p><div class="compact-lyrics-grid">'+matches.map(item=>'<a class="compact-lyric-card" href="'+esc(item.href)+'"><span class="compact-card-copy"><span class="compact-badge">'+(item.type==='lyrics'?'LYRICVERSE · LYRICS':'LYRICVERSE · SONG DETAILS')+'</span><strong>'+esc(item.title)+'</strong><span class="compact-artist">'+esc(item.artist)+'</span><span class="compact-open">'+(item.type==='lyrics'?'Read lyrics ↗':'View song ↗')+'</span></span></a>').join('')+'</div></section>':'';
 const external=providerSongs.filter(song=>['LRCLIB','Genius','Web lyrics search'].includes(song.provider)).filter(song=>song.provider==='Web lyrics search'||!internalSongLink(song,{published:publishedSongs,catalog:allSongs})).sort((a,b)=>Number(b.provider==='Web lyrics search')-Number(a.provider==='Web lyrics search'));
 const externalHTML=providerLoading?'<p>Searching music sources…</p>':providerError?'<p>External search is temporarily unavailable.</p>':external.length?'<div class="compact-lyrics-grid">'+external.map(song=>(song.provider==='LRCLIB'?'<button type="button" class="compact-lyric-card" data-lrclib-id="'+esc(String(song.id||''))+'">':'<a class="compact-lyric-card" href="'+esc(song.url)+'" target="_blank" rel="noopener noreferrer">')+'<span class="compact-card-copy"><span class="compact-badge">'+esc(song.provider)+'</span><strong>'+esc(song.provider==='Web lyrics search'?'Search lyrics across the web':song.title)+'</strong><span class="compact-artist">'+esc(song.provider==='Web lyrics search'?'Additional external results':song.artist)+'</span><span class="compact-open">'+(song.provider==='LRCLIB'?'Read source lyrics':'Find lyrics ↗')+'</span></span>'+(song.provider==='LRCLIB'?'</button>':'</a>')).join('')+'</div>':localHTML?'':'<p>No additional sources found.</p>';
 const reader=activeLrclibLyrics?'<article class="lyrics-reader"><h3>'+esc(activeLrclibLyrics.title)+' — '+esc(activeLrclibLyrics.artist)+'</h3><pre style="white-space:pre-wrap;font:inherit;line-height:1.9">'+esc(activeLrclibLyrics.lyrics)+'</pre></article>':'';
 return localHTML+'<section class="provider-results" aria-label="External music sources"><h2>Additional sources</h2><p class="library-description">External links appear only as a fallback when a matching LyricVerse song is not available.</p>'+reader+externalHTML+'</section>';
}
function searchPageHTML(){return `${navHTML()}<main id="app-main" tabindex="-1" class="discovery-main search-page neon-search-page"><section class="search-page-header neon-search-header"><span class="section-kicker">EXPLORE THE MUSIC UNIVERSE</span><h1>Discover your next song.</h1><p class="library-description">Search songs and artists. Uploaded LyricVerse lyrics appear alongside clearly identified external sources.</p><div class="neon-search-control">${searchHTML()}</div><div class="search-language-bar"><span>Lyrics language</span>${languageSwitchHTML()}</div></section><div class="neon-search-content">${providerResultsHTML()}</div></main>${bottomNavHTML()}`;}
function libraryEmptyHTML(){
 const published=publishedSongs.find(s=>s?.status==='published'&&(s.accessTier||'free')==='free'&&typeof s.lyrics==='string'&&s.lyrics.trim()&&/^[a-f0-9]{24}$/i.test(String(s._id||'')));
 const recommended=published||allSongs[0];
 const sampleHref=published?'#/original/'+encodeURIComponent(String(published._id)):recommended?songHref(recommended):'#/search';
 const heading=authUser?'A collection worth coming back to.':'Every great playlist starts somewhere.';
 const description=authUser?'Your library is ready. Find a track that moves you, then tap its heart to keep it close.':'Create a free account to save the songs you love and pick up your collection on your next visit.';
 return `<section class="lv-library-empty" aria-labelledby="lv-library-empty-title"><div class="lv-library-empty-copy"><span class="lv-library-empty-kicker">YOUR PRIVATE LISTENING SPACE <span aria-hidden="true">✦</span></span><h2 id="lv-library-empty-title">${heading}</h2><p>${description}</p><div class="lv-library-empty-actions"><a class="button button-primary lv-library-empty-primary" href="${authUser?'#/search':'#/profile'}">${authUser?'Discover songs':'Sign in to save songs'} <span aria-hidden="true">↗</span></a><a class="button button-secondary lv-library-empty-secondary" href="${sampleHref}">Explore a song <span aria-hidden="true">→</span></a></div><div class="lv-library-empty-guide"><span class="lv-library-empty-guide-dot" aria-hidden="true"></span>${authUser?'Find a song · tap ♡ · see it here':'Discover music · save favorites · return anytime'}</div></div><div class="lv-library-empty-stage" aria-hidden="true"><div class="lv-library-empty-orbit lv-library-empty-orbit-one"></div><div class="lv-library-empty-orbit lv-library-empty-orbit-two"></div><div class="lv-library-empty-record"><div class="lv-library-empty-record-label"><span>LV</span><i></i></div></div><div class="lv-library-empty-card"><span class="lv-library-empty-card-art">♫</span><span class="lv-library-empty-card-copy"><strong>YOUR SOUNDTRACK</strong><small>Made by you, one song at a time.</small></span></div></div></section>`;
}
function libraryHTML(){const results=allSongs.filter(s=>state.saved.includes(s.id));return `${navHTML()}<main id="app-main" tabindex="-1" class="discovery-main search-page neon-library"><section class="search-page-header"><span class="section-kicker">YOUR COLLECTION</span><h1>Your library</h1><p class="library-description">${results.length?'Saved songs':authUser?'Your saved soundtrack is waiting.':'Sign in to keep your favorites together.'}</p></section>${results.length?sectionHTML('Saved songs',results,results.slice(0,2)):libraryEmptyHTML()}</main>${bottomNavHTML()}`;}
function authHTML(){
 const emailEnabled=authConfig.emailEnabled;
 const googleEnabled=!!authConfig.googleClientId;
 const status=!emailEnabled&&!googleEnabled?(authConfigError||'Authentication is not configured on the API. Check AUTH_SECRET, MONGODB_URI, and GOOGLE_CLIENT_ID in Render.'):'';
 return `<main id="app-main" tabindex="-1" class="auth-gate"><section class="auth-panel"><h1>Welcome to LyricVerse</h1><p>Sign in with Google or a verified email address.</p>${googleEnabled?'<div id="google-signin" class="auth-google"></div>':''}${emailEnabled?`<p>Or continue with email</p><form id="auth-form"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" required value="${esc(authEmail)}">${authStep==='verify'?'<label for="auth-code">Verification code</label><input id="auth-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required>':''}<button class="button button-primary" type="submit">${authStep==='verify'?'Verify email':'Send verification code'}</button></form>`:''}<p role="status" class="auth-status">${esc(status)}</p><p role="alert" class="auth-error">${esc(authError)}</p></section></main>`;
}
function profileHTML(){
 if(!authUser)return `${navHTML()}${authHTML()}${bottomNavHTML()}`;
 const name=esc(authUser.name||authUser.email.split('@')[0]);
 const genres=['Pop','Rock','Hip-Hop','R&B','Indie','Bollywood','Classical','Electronic','Other'];
 return `${navHTML()}<main id="app-main" tabindex="-1" class="profile-main neon-profile"><section class="neon-profile-hero"><span class="section-kicker">YOUR MUSIC UNIVERSE</span><h1>Your profile</h1><p>Every song tells part of your story.</p></section><section class="profile-panel"><h2>Account settings</h2><p>Manage your account and music preferences.</p><div class="profile-identity"><span class="profile-avatar" aria-hidden="true">${esc((authUser.name||authUser.email).charAt(0).toUpperCase())}</span><div><strong>${name}</strong><p>${esc(authUser.email)}</p><small>Verified account</small></div></div><form id="profile-form"><label for="profile-name">Display name</label><input id="profile-name" name="name" maxlength="80" required value="${esc(authUser.name||'')}"><label for="profile-language">Preferred language</label><select id="profile-language" name="preferredLanguage"><option value="en" ${authUser.preferredLanguage!=='hi'?'selected':''}>English</option><option value="hi" ${authUser.preferredLanguage==='hi'?'selected':''}>Hindi</option></select><fieldset class="profile-genres"><legend>Favorite genres</legend>${genres.map(g=>`<label><input type="checkbox" name="genre" value="${esc(g)}" ${(authUser.favoriteGenres||[]).includes(g)?'checked':''}> ${esc(g)}</label>`).join('')}</fieldset><button class="button button-primary" type="submit">Save profile</button><p role="status" id="profile-status"></p></form><div class="profile-actions"><a class="button button-secondary" href="#/library">Saved Songs (${state.saved.length})</a><button class="button button-secondary" type="button" data-action="logout">Sign out</button></div></section><section class="profile-saved-section neon-favorites" aria-label="Saved Songs"><div class="section-heading"><h2>Saved Songs</h2><a href="#/library">View all →</a></div>${state.saved.length?`<div class="profile-saved-grid">${allSongs.filter(song=>state.saved.includes(song.id)).map(song=>songCardHTML(song)).join("")}</div>`:`<p class="library-description">No saved songs yet. Tap the heart on a song to add it here.</p>`}</section></main>${bottomNavHTML()}`;
}
async function authCall(path,data){const r=await fetch(API_URL+'/api/v1/auth/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const payload=await r.json();if(!r.ok)throw Error(payload.error||'Sign-in failed');return payload.data;}
async function finishAuth(data){authToken=data.token;safeStorageSet('sessionStorage','lyricverse:session',authToken);authUser=data.user;state.saved=authUser.savedSongs||[];authError='';render();}
async function initGoogleAuth(){
 if(authUser||!authConfig.googleClientId||!document.querySelector('#google-signin'))return;
 try{
  if(!googleScriptPromise)googleScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>reject(Error('google_script_unavailable'));document.head.append(script);}).catch(error=>{googleScriptPromise=null;throw error;});
  await googleScriptPromise;
  const target=document.querySelector('#google-signin');if(!target||!window.google?.accounts?.id)return;
  google.accounts.id.initialize({client_id:authConfig.googleClientId,callback:async response=>{try{await finishAuth(await authCall('google',{credential:response.credential}));}catch(e){authError=e.message;render();}}});
  google.accounts.id.renderButton(target,{type:'standard',theme:'outline',size:'large',shape:'rectangular',text:'signin_with',width:Math.max(200,Math.min(320,Math.floor(target.getBoundingClientRect().width||window.innerWidth-48)))});
 }catch{const target=document.querySelector('#google-signin');if(target)target.innerHTML='<p role="alert">Google sign-in could not load.</p><button type="button" class="button button-secondary" data-action="retry-google">Retry Google sign-in</button>';}
}
function render(){
 const route=currentRoute();
 if(route.page==='original')void ensureOriginalSong(route.slug);
 stopMusicOrbs();
 if(!authConfigChecked){app.innerHTML='<main id="app-main" tabindex="-1" role="status" class="auth-loading">Loading LyricVerse…</main>';return;}
 if(route.page==='profile'&&!authUser){app.innerHTML=profileHTML();mountMotion(app);void initGoogleAuth();return;}
 app.innerHTML=route.page==='profile'?profileHTML():route.page==='original'?originalReaderHTML():route.page==='lyrics'?readerHTML():route.page==='search'?searchPageHTML():route.page==='library'?libraryHTML():route.page==='info'?infoHTML():homeHTML();
 document.title=route.page==='lyrics'?`${allSongs.find(s=>s.id===route.slug)?.title||'Lyrics'} — LyricVerse`:'LyricVerse — Every song has a story';
 if(route.page==='lyrics'){document.documentElement.style.setProperty('--lyrics-adjust',`${state.fontBoost}px`);}else document.documentElement.style.removeProperty('--lyrics-adjust');
 mountMotion(app);
 if(route.page==='home')initSongBanner();
 if(originalDismissed)document.querySelector('.original-floater')?.remove();if(state.toast)showToast(state.toast,false);
 if(route.page==='profile'&&!authUser)void initGoogleAuth();
}
function toast(s){state.toast=s;clearTimeout(state.toastTimer);showToast(s,true);state.toastTimer=setTimeout(()=>{state.toast='';document.querySelector('.toast')?.remove();},3800);}
function showToast(s){document.querySelector('.toast')?.remove();const div=document.createElement('div');div.className='toast';div.role='status';div.textContent=s;document.body.appendChild(div);}
function updateSearchResults(form){const input=form.querySelector('input');const q=input.value.trim();let results=form.querySelector('.search-results');if(!results)return;if(!q){results.hidden=true;results.innerHTML='';return;}const data=localSongMatches(q,{published:publishedSongs,catalog:allSongs}).slice(0,5);results.hidden=false;results.innerHTML=data.length?data.map(s=>`<a href="${esc(s.href)}" class="search-result"><span>${esc(s.title)}</span><small>${esc(s.artist)} · ${s.type==='lyrics'?'Read lyrics':'Song details'}</small></a>`).join(''):'<p class="empty-search">Search for songs to explore available lyrics.</p>';}
app.addEventListener('submit',async e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const form=e.target;const button=form.querySelector('button[type="submit"]');const status=form.querySelector('#profile-status');button.disabled=true;status.textContent='Saving…';try{const response=await fetch(API_URL+'/api/v1/auth/profile',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+authToken},body:JSON.stringify({name:form.elements.name.value,preferredLanguage:form.elements.preferredLanguage.value,favoriteGenres:[...form.querySelectorAll('input[name="genre"]:checked')].map(el=>el.value)})});const payload=await response.json();if(!response.ok)throw Error(payload.error||'Unable to save profile');authUser=payload.data.user;state.language=authUser.preferredLanguage;safeStorageSet('localStorage','lyricverse:language',state.language);render();document.querySelector('#profile-status').textContent='Profile saved successfully.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
app.addEventListener('submit',e=>{const form=e.target.closest('[data-search]');if(!form)return;e.preventDefault();const input=form.querySelector('input');state.query=input.value.trim();location.hash='#/search';void loadProviderSearch();});
app.addEventListener('input',e=>{if(e.target.matches('input[name="q"]')){state.query=e.target.value;updateSearchResults(e.target.closest('form'));}});
async function toggleFavorite(id){if(!authUser){location.hash='#/profile';toast('Sign in to save songs to your profile.');return;}const previous=[...state.saved];state.saved=previous.includes(id)?previous.filter(x=>x!==id):[...previous,id];render();try{const response=await fetch(API_URL+'/api/v1/auth/favorites',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+authToken},body:JSON.stringify({savedSongs:state.saved})});const payload=await response.json();if(!response.ok)throw Error(payload.error||'Unable to save song');authUser=payload.data.user;state.saved=authUser.savedSongs||[];render();}catch(error){state.saved=previous;render();toast(error.message);}}
app.addEventListener('click',async e=>{const heart=e.target.closest('[data-favorite-id]');if(heart){e.preventDefault();await toggleFavorite(heart.dataset.favoriteId);return;}if(e.target.closest('[data-action="dismiss-original"]')){originalDismissed=true;document.querySelector('.original-floater')?.remove();return;}const rating=e.target.closest('[data-rating]');if(rating){void submitRating(Number(rating.dataset.rating));return;}const scroll=e.target.closest('[data-scroll-to]');if(scroll){e.preventDefault();const target=scroll.dataset.scrollTo;if(!['moods','how-it-works'].includes(target))return;const section=document.getElementById(target);if(section){section.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}else{safeStorageSet('sessionStorage','lyricverse:pending-section',target);location.hash='#/';}return;}const pause=e.target.closest('[data-action="pause-rotation"]');if(pause){state.rotationPaused=!state.rotationPaused;pause.setAttribute('aria-pressed',String(state.rotationPaused));pause.setAttribute('aria-label',state.rotationPaused?'Resume headline rotation':'Pause headline rotation');pause.textContent=state.rotationPaused?'▶':'Ⅱ';return;}const rotate=e.target.closest('[data-action="rotate-headline"]');if(rotate){advanceHeroRotators();return;}const mood=e.target.closest('[data-mood]');if(mood){state.filter=mood.dataset.mood;}const language=e.target.closest('[data-language]');if(language){const next=language.dataset.language;if(!['hi','en','pa'].includes(next))return;state.language=next;state.filter='All';state.query='';localStorage.setItem('lyricverse:language',next);realCatalog=[];const previousScroll=window.scrollY;render();window.scrollTo(0,previousScroll);return;}const genre=e.target.closest('[data-genre]');if(genre){state.filter=genre.dataset.genre;render();if(state.filter==='Hindi-English Mix')document.getElementById('hindi-english-songs')?.scrollIntoView({behavior:'smooth',block:'start'});return;}const tab=e.target.closest('[data-tab]');if(tab){state.readerTab=tab.dataset.tab;render();return;}const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='focus-lyrics'){e.preventDefault();const route=currentRoute();const source=route.page==='original'?publishedSongs.find(song=>String(song._id)===route.slug):route.page==='lyrics'?publishedMatch(allSongs.find(song=>song.id===route.slug),publishedSongs):null;if(source?.lyrics?.trim())openFocusReader({title:source.title,artist:source.artist,lyrics:source.lyrics,trigger:button});else toast('Published lyrics are not available for this song.');return;}if(action==='menu'){state.menu=!state.menu;render();}if(action==='save'){const song=allSongs.find(s=>s.id===currentRoute().slug)||readerSong;await toggleFavorite(song.id);}if(action==='font-size'){state.fontBoost=(state.fontBoost+2)%8;document.documentElement.style.setProperty('--lyrics-adjust',state.fontBoost+'px');toast('Text size adjusted');}if(action==='translate')toast('Translations will appear when licensed content is connected.');if(action==='preview'){
 const route=currentRoute();
 const song=route.page==='original'
  ?publishedSongs.find(x=>String(x._id)===route.slug)
  :(allSongs.find(x=>x.id===route.slug)||readerSong);
 if(!song?.title||!song?.artist)return;
 const routeKey=route.page+':'+route.slug;
 const songId=String(song._id||song.id);
 state.youtubePreviewLoading=true;state.youtubePreview=null;render();
 try{
  const response=await fetch(API_URL+'/api/v1/media/youtube-preview?title='+encodeURIComponent(song.title)+'&artist='+encodeURIComponent(song.artist));
  if(!response.ok)throw Error('preview_unavailable');
  const payload=await response.json();
  const videoId=typeof payload?.data?.videoId==='string'&&/^[A-Za-z0-9_-]{11}$/.test(payload.data.videoId)?payload.data.videoId:null;
  if(currentRoute().page+':'+currentRoute().slug===routeKey)state.youtubePreview={songId,videoId};
 }catch{
  if(currentRoute().page+':'+currentRoute().slug===routeKey)state.youtubePreview={songId,videoId:null};
 }finally{
  if(currentRoute().page+':'+currentRoute().slug===routeKey){
   state.youtubePreviewLoading=false;render();
   document.querySelector('.youtube-preview-panel')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});
  }
 }
}if(action==='share'){try{await navigator.clipboard.writeText(location.href);toast('Link copied');}catch{toast('Share this page using the address bar.')}}if(action==='sign-in'){e.preventDefault();location.hash='#/profile';render();}if(action==='retry-google'){e.preventDefault();void initGoogleAuth();}if(action==='logout'){e.preventDefault();const token=authToken;authToken='';authUser=null;authStep='email';authError='';safeStorageRemove('sessionStorage','lyricverse:session');render();if(token)void fetch(API_URL+'/api/v1/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+token}}).catch(()=>{});}});
function renderRouteTransition(){
 const update=()=>{
  window.scrollTo(0,0);
  render();
  const pending=safeStorageGet('sessionStorage','lyricverse:pending-section');
  if(pending&&currentRoute().page==='home'){
   safeStorageRemove('sessionStorage','lyricverse:pending-section');
   requestAnimationFrame(()=>document.getElementById(pending)?.scrollIntoView({
    behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'
   }));
  }
 };
 if(typeof document.startViewTransition==='function'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
  try{const transition=document.startViewTransition(update);void transition.finished.catch(()=>{});return;}
  catch{ /* Browser did not accept a transition; render directly. */ }
 }
 update();
}
window.addEventListener('hashchange',()=>{
 state.menu=false;state.readerTab='Lyrics';state.youtubePreview=null;state.youtubePreviewLoading=false;renderRouteTransition();
});
window.addEventListener('resize',()=>{if(currentRoute().page==='lyrics')render();},{passive:true});
let rotateTimer;function advanceHeroRotators(){
 state.headlineIndex=(state.headlineIndex+1)%HERO_MESSAGES.length;
 state.heroHighlightIndex=(state.heroHighlightIndex+1)%HERO_HIGHLIGHTS.length;
 const small=document.querySelector('[data-rotator-text]');
 if(small)small.textContent=HERO_MESSAGES[state.headlineIndex];
 const main=document.querySelector('[data-hero-highlight]');
 if(main){main.textContent=HERO_HIGHLIGHTS[state.heroHighlightIndex];main.classList.remove('highlight-sweep');void main.offsetWidth;main.classList.add('highlight-sweep');}
}
function rotateStart(){
 if(rotateTimer)clearInterval(rotateTimer);
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 rotateTimer=setInterval(()=>{
  if(document.hidden||state.rotationPaused||currentRoute().page!=='home')return;
  advanceHeroRotators();
 },4600);
}
rotateStart();
render();

loadOriginalCompositions();

loadRatingSummary();

// LRCLIB reader: display only cleared tracks; show attribution and source link.
document.addEventListener('click',event=>{const pearl=event.target.closest('a.lyric-pearl');if(!pearl)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;event.preventDefault();if(pearl.classList.contains('is-popping'))return;pearl.classList.add('is-popping');const destination=pearl.getAttribute('href');setTimeout(()=>{location.hash=destination;},430);});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-lrclib-id]');if(!button)return;const id=Number(button.dataset.lrclibId);if(!Number.isSafeInteger(id)||id<1)return;button.disabled=true;button.setAttribute('aria-busy','true');try{const response=await fetch(API_URL+'/api/v1/providers/lrclib/lyrics?id='+id);const payload=await response.json();if(!response.ok||payload.data?.status!=='available'){toast(payload.data?.status==='permission_required'?'Lyrics publication pending permission':'Lyrics unavailable');return;}activeLrclibLyrics=payload.data;render();}catch{toast('Lyrics unavailable');}finally{button.disabled=false;button.removeAttribute('aria-busy');}});

document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const fd=new FormData(e.target);authEmail=String(fd.get('email')||'').trim();authError='';try{if(authStep==='verify'){await finishAuth(await authCall('email/verify',{email:authEmail,code:String(fd.get('code')||'')}));}else{await authCall('email/request',{email:authEmail});authStep='verify';render();}}catch(err){authError=err.message;render();}});
async function initializeUserAccess(){
 // Show the public site immediately; a sleeping backend must not leave mobile visitors on a blank page.
 authConfigChecked=true;render();
 try{
  const r=await fetch(API_URL+'/api/v1/auth/config',{signal:typeof AbortSignal.timeout==='function'?AbortSignal.timeout(12000):undefined});
  if(r.ok){const config=await r.json();authConfig={googleClientId:config.data?.googleClientId||null,emailEnabled:config.data?.emailEnabled===true};authReady=config.data?.authReady===true;authConfigError='';}
  else authConfigError='Authentication API returned HTTP '+r.status+'. Check API and CORS settings.';
 }catch{authConfigError='Authentication API is unreachable. Check the API service, network, and CORS settings.';}
 if(authToken){
  try{const r=await fetch(API_URL+'/api/v1/auth/me',{headers:{Authorization:'Bearer '+authToken},signal:typeof AbortSignal.timeout==='function'?AbortSignal.timeout(10000):undefined});
   if(r.ok){const payload=await r.json();authUser=payload.data?.user||null;state.saved=authUser?.savedSongs||[];}
   else if(r.status===401){safeStorageRemove('sessionStorage','lyricverse:session');authToken='';}
  }catch{authError='Unable to verify session. Please retry.';}
 }
 render();
}
initializeUserAccess();
// A remote artwork host may reject embeds; walk through the same gallery image
// used on discovery cards, then fall back to the local generated album graphic.
document.addEventListener('error',event=>{const img=event.target;if(img?.matches?.('img[data-artwork-fallback]'))recoverReaderArtwork(img);},true);
